@startuml

class Employee {
  + name : string
  + socialSecurityNumber : string
}

class Planner extends Employee {
  + username : string
  + password : string
}

class AdministrativeStaff extends Employee {
  + username : string
  + password : string
  + fieldOfActivity : string
}

class Customer {
  + name : string
  + billingAddress : string
}

class PartnerCompany {
  + name : string
  + address : string
}

class Vehicle {
  + licensePlateNumber : string
  + mileage : int
}

class RefrigeratedTruck extends Vehicle {}

class SmallVan extends Vehicle {}

class LoadingPlatform extends Vehicle {}

class BoxTruck extends Vehicle {}

class RepairShop {
  + name : string
  + address : string
}

class Repair {
  + duration : string
  + cost : double
}

class Order {
  + packageSize : string
  + comment : string
  + startTime : datetime
  + finishTime : datetime
  + pickUpAddress : string
  + deliveryAddress : string
}

Employee "1" -- "*" Repair : takes vehicle to
Repair "*" -- "1" Vehicle : involves
Repair "*" -- "1" RepairShop : performed at

Driver "0..*" -- "*" Order : assigned to
Driver "1" -- "*" Order : completes
Vehicle "1" -- "*" Order : used in
Planner "1" -- "*" Order : assigns
Customer "1" -- "*" Order : is client of
AdministrativeStaff "1" -- "*" Order : places
PartnerCompany "1" -- "*" Order : places

@enduml

